import { readJsonFile } from "./readJson.js";

// Payload is generated by the pack-ev repo:
// `uv run pack-ev site-export --site <this repo>` writes data/packev.json.
export function getPackEvData() {
  return readJsonFile("data/packev.json", {
    requiredKeys: ["meta", "roles", "cross", "boosters"],
    nonEmpty: ["boosters"],
    hint: "run `uv run pack-ev site-export --site <this repo>` in the pack-ev repo",
  });
}
